using Kairnfall.Core;

namespace Kairnfall.Client;

/// <summary>Presentation-side pickup selection. The server still validates ownership and transfer.</summary>
public static class InteractionRules
{
    public static WorldTarget? NearbyLoot(Character self,IEnumerable<LootPile> piles,Catalog data,double time)
    {
        if(self.Health<=0||!self.Position.Finite||!double.IsFinite(time)) return null;
        var pile=piles.Where(value=>value.Zone==self.Zone&&value.Position.Finite&&value.Expires>time)
            .Where(value=>value.Owner==self.Id||value.PublicAt<=time||(value.Party!=""&&value.Party==self.Party))
            .Where(value=>value.Gold>0||value.Items.Count>0)
            .Where(value=>self.Position.Distance(value.Position)<=2.15)
            .Where(value=>WorldMap.LineOfSight(data.Zone(self.Zone),self.Position,value.Position))
            .OrderBy(value=>self.Position.Distance(value.Position)).ThenBy(value=>value.Id,StringComparer.Ordinal).FirstOrDefault();
        if(pile is null) return null;
        string name=pile.Items.Count==1?data.Item(pile.Items[0].Template).Name:pile.Items.Count>1?"Dropped items":"Gold";
        return new WorldTarget("loot",pile.Id,name,pile.Position);
    }
}

